# Checker GUI: embedded UTF-8 sources, decoded into one isolated session directory.
# Main UI: Windows Forms. Scanner runs in a hidden child process only on user action.
# Original scanner: https://github.com/Iwtyys/readiness-skytime (IwTu).
# The access-key gate remains enabled. Only this session directory is cleaned up.
& {
    $ErrorActionPreference = 'Stop'
    $checkerSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
    $checkerEngineSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
    $checkerWorkerSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
    $checkerTempRoot = [System.IO.Path]::GetFullPath([System.IO.Path]::GetTempPath()).TrimEnd([char]'\')
    $checkerRunName = 'Checker-' + [guid]::NewGuid().ToString('N')
    $checkerRuntime = [System.IO.Path]::GetFullPath((Join-Path $checkerTempRoot $checkerRunName))
    $checkerWorker = $null
    try {
        if ((Split-Path -Parent $checkerRuntime) -ine $checkerTempRoot) {
            throw 'Invalid Checker temporary directory.'
        }
        New-Item -ItemType Directory -Path $checkerRuntime -ErrorAction Stop | Out-Null
        $checkerMain = Join-Path $checkerRuntime 'CheckerMain.ps1'
        [System.IO.File]::WriteAllText($checkerMain, $checkerSource, (New-Object System.Text.UTF8Encoding($true)))
        [System.IO.File]::WriteAllText((Join-Path $checkerRuntime 'Engine.ps1'), $checkerEngineSource, (New-Object System.Text.UTF8Encoding($true)))
        [System.IO.File]::WriteAllText((Join-Path $checkerRuntime 'Worker.ps1'), $checkerWorkerSource, (New-Object System.Text.UTF8Encoding($true)))
        $checkerBootstrap = @'
$ErrorActionPreference = 'Stop'
$checkerWorkingDirectory = Split-Path -Parent $PSCommandPath
$env:TEMP = $checkerWorkingDirectory
$env:TMP = $checkerWorkingDirectory
Set-Location -LiteralPath $checkerWorkingDirectory
try {
    & (Join-Path $checkerWorkingDirectory 'CheckerMain.ps1')
} catch {
    Add-Type -AssemblyName System.Windows.Forms
    [void][System.Windows.Forms.MessageBox]::Show(('Не удалось открыть Checker: ' + $_.Exception.Message),'Checker')
    exit 1
}
'@
        $checkerBootstrapPath = Join-Path $checkerRuntime 'Start.ps1'
        [System.IO.File]::WriteAllText($checkerBootstrapPath, $checkerBootstrap, (New-Object System.Text.UTF8Encoding($true)))
        $checkerPowerShell = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $checkerArguments = '-NoProfile -STA -WindowStyle Hidden -ExecutionPolicy Bypass -File "' + $checkerBootstrapPath + '"'
        Write-Host 'Запуск Checker. После закрытия приложения временная папка будет удалена.' -ForegroundColor Gray
        $checkerWorker = Start-Process -FilePath $checkerPowerShell -ArgumentList $checkerArguments -Verb RunAs -PassThru
        $checkerWorker.WaitForExit()
    } catch {
        Write-Host ('Не удалось запустить Checker: ' + $_.Exception.Message) -ForegroundColor Red
    } finally {
        # Never touch Windows logs or other temporary folders.
        if ($null -ne $checkerWorker -and -not $checkerWorker.HasExited) {
            $checkerWorker.WaitForExit()
        }
        if (Test-Path -LiteralPath $checkerRuntime) {
            $checkerResolved = [System.IO.Path]::GetFullPath($checkerRuntime)
            $checkerParent = Split-Path -Parent $checkerResolved
            $checkerLeaf = Split-Path -Leaf $checkerResolved
            $checkerDirectory = Get-Item -LiteralPath $checkerResolved -Force
            $checkerIsLink = ($checkerDirectory.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0
            if ($checkerParent -ine $checkerTempRoot -or $checkerLeaf -cne $checkerRunName -or $checkerIsLink) {
                Write-Warning 'Checker cleanup skipped: unexpected working directory.'
            } else {
                for ($checkerAttempt = 0; $checkerAttempt -lt 3; $checkerAttempt++) {
                    try {
                        Remove-Item -LiteralPath $checkerResolved -Recurse -Force -ErrorAction Stop
                        break
                    } catch {
                        if ($checkerAttempt -lt 2) { Start-Sleep -Milliseconds 400 }
                        else { Write-Warning ('Checker temporary files could not be removed: ' + $checkerResolved) }
                    }
                }
            }
        }
    }
}
